var DISMISS_COOKIE = 'optlyExitModalClosed';

utils.waitForElement('body').then(function(element){
  var html = extension.$html;
  element.insertAdjacentHTML('afterbegin', html);

  // Already dismissed recently? Don't arm the trigger at all.
  if (document.cookie.indexOf(DISMISS_COOKIE + '=') !== -1) return;

  // Bind the close button once, not on every mouseleave
  bindCloseBtn();

  element.addEventListener('mouseleave', onMouseLeave);

  function onMouseLeave() {
    showPopup();
  }

  function bindCloseBtn() {
    document.querySelector('.optly-modal-close').addEventListener('click', function(e){
      e.preventDefault();
      hidePopup();
      // Stop re-triggering on this page
      element.removeEventListener('mouseleave', onMouseLeave);
      // Stop re-triggering on future pages for 24 hours
      document.cookie = DISMISS_COOKIE + '=true; path=/; max-age=' + (24 * 60 * 60);
    });
  }
});

